def dependency_of_fetches(fetches, op):
    """
    Check that op is in the subgraph induced by the dependencies of fetches.
    fetches may have more general structure.

    Args:
        fetches: An argument to `sess.run`. Nested structure will affect performance.
        op (tf.Operation or tf.Tensor):

    Returns:
        bool: True if any of `fetches` depend on `op`.
    """
    if isinstance(fetches, tf.Tensor):
        fetches = [fetches]
    if isinstance(op, tf.Tensor):
        op = op.op
    if isinstance(op, tf.Operation):
        op = [op]
    if not isinstance(op, list):
        raise TypeError("op must be a tf.Operation or a list of tf.Operations")
    if not isinstance(fetches, list):
        raise TypeError("fetches must be a tf.Tensor or a list of tf.Tensors")
    for fetch in fetches:
        if isinstance(fetch, tf.Tensor):
            fetch = fetch.op
        if isinstance(fetch, tf.Operation):
            fetch = [fetch]
        if not isinstance(fetch, list):
            raise TypeError("fetches must be a tf.Tensor or a list of tf.Tensors")
        for f in fetch:
            if f in op:
                return True
            if f.type == "Placeholder":
                continue
            for i in range(len(f.inputs)):
                if dependency_of_fetches(fetches, f.inputs[i].op):
                    return True
    return False

